"""DC contract v1 core: lexical-free alignment (align_pair) and logical relation (pair_relation) of two FOL formulas.

Names of predicates and constants are NEVER read as words: they are opaque symbols. Every map is arity-preserving
and chosen by solver search only; ordering inside each level is deterministic (arity profile, then occurrence
count, then first-occurrence position), and the structural-fingerprint order (DC_fp) is a declared variant.

Pipeline for one pair (A, B) [B is read in A's vocabulary]:
  L1  bijections of equal arity profiles (vendor fol_equiv style, cap 5,040 maps; exhaustive when total <= cap)
  L2  partial injective arity-preserving maps covering >= 50% of B's predicate OCCURRENCES (cap 2,000);
      unmapped B predicates stay fresh symbols (free in every check)
  L3  granularity definitions: <= 2 predicates of one side defined as a conjunction of <= 2 literals over the
      other side's predicates with arity-consistent slot patterns (cap 300 definition sets; both directions)
For each map: a vectorised numpy evaluator refutes entailment directions on (i) solver-found models and
countermodels of A, (ii) models/countermodels of B transported through the map, (iii) seeded random structures
(domains 2 and 3). Directions that survive are decided by vendor fol_equiv.bounded_check (z3 propositional
grounding over domains 1..4, 5 s per call) and then an unbounded z3 entailment check (5 s).
"""
from __future__ import annotations

import itertools
import math
import random
import sys
import time
from collections import Counter, defaultdict
from pathlib import Path

import numpy as np
import z3

_V = Path(__file__).resolve().parents[1] / "vendor" / "ds"
if str(_V) not in sys.path:
    sys.path.insert(0, str(_V))
from fol_equiv import _Grounder, bounded_check  # noqa: E402  (vendor, READ-ONLY copy)
from fol_parse import SYM, normalize_arity_overloads, parse, signature, to_str  # noqa: E402

REL_ORDER = {"EQUIV": 4, "STRONGER": 3, "WEAKER": 3, "COMPATIBLE-INCOMPARABLE": 2, "CONTRADICTORY": 1}
INVERSE = {"STRONGER": "WEAKER", "WEAKER": "STRONGER"}
DEFAULT_LIMITS = {"l1_cap": 5040, "l2_cap": 2000, "l3_cap": 300, "l2_min_cov": 0.5, "l3_max_defs": 2,
                  "l3_max_lits": 2, "domains": (1, 2, 3, 4), "z3_timeout_ms": 5000, "pair_seconds": 20.0,
                  "order": "default", "n_random": 24, "n_models": 6, "max_z3_maps": 40}


# ============================================================================== formula container
def _alpha(ast, env=None, counter=None):
    """alpha-rename bound variables to v0, v1, ... (unique per binder)."""
    env = env or {}
    counter = counter if counter is not None else [0]
    op = ast[0]
    if op in ("forall", "exists"):
        nv = f"v{counter[0]}"
        counter[0] += 1
        return (op, nv, _alpha(ast[2], {**env, ast[1]: nv}, counter))
    if op == "not":
        return ("not", _alpha(ast[1], env, counter))
    if op in SYM:
        return (op, _alpha(ast[1], env, counter), _alpha(ast[2], env, counter))
    if op == "atom":
        return ("atom", ast[1], tuple(("var", env.get(t[1], t[1])) if t[0] == "var" else t for t in ast[2]))
    if op == "eq":
        return ("eq",) + tuple(("var", env.get(t[1], t[1])) if t[0] == "var" else t for t in ast[1:])
    raise ValueError(op)


def walk_atoms(ast, path=(), pol=1, ante=False, out=None):
    """yields (name, args, polarity, in_antecedent, depth, quantified-var co-occurrence) for every atom occurrence."""
    out = [] if out is None else out
    op = ast[0]
    if op in ("forall", "exists"):
        walk_atoms(ast[2], path + (op,), pol, ante, out)
    elif op == "not":
        walk_atoms(ast[1], path + ("not",), -pol, ante, out)
    elif op == "imp":
        walk_atoms(ast[1], path + ("imp_l",), -pol, True, out)
        walk_atoms(ast[2], path + ("imp_r",), pol, ante, out)
    elif op in ("iff", "xor"):
        walk_atoms(ast[1], path + (op,), 0, ante, out)
        walk_atoms(ast[2], path + (op,), 0, ante, out)
    elif op in SYM:
        walk_atoms(ast[1], path + (op,), pol, ante, out)
        walk_atoms(ast[2], path + (op,), pol, ante, out)
    elif op == "atom":
        out.append({"name": ast[1], "args": ast[2], "pol": pol, "ante": ante, "depth": len(path),
                    "negated": path[-1:] == ("not",) if path else False})
    return out


class Formula:
    """Parsed, arity-normalised, alpha-renamed formula plus lexical-free structural statistics."""

    def __init__(self, fol: str):
        self.fol = fol
        pr = parse(fol or "")
        self.ok = pr.ok
        self.error = pr.error
        if not pr.ok:
            return
        self.ast = _alpha(normalize_arity_overloads(pr.ast))
        self.preds, cs = signature(self.ast)
        self.consts = sorted(cs)
        occ = walk_atoms(self.ast)
        self.occ = occ
        self.n_occ = Counter(o["name"] for o in occ)
        first = {}
        for i, o in enumerate(occ):
            first.setdefault(o["name"], i)
        self.first = {p: first.get(p, 0) / max(1, len(occ)) for p in self.preds}
        cfirst = {}
        for i, o in enumerate(occ):
            for t in o["args"]:
                if t[0] == "const":
                    cfirst.setdefault(t[1], i)
        self.cfirst = {c: cfirst.get(c, 0) / max(1, len(occ)) for c in self.consts}
        self.c_occ = Counter(t[1] for o in occ for t in o["args"] if t[0] == "const")
        self.vars = sorted({v for v in _bound_vars(self.ast)}, key=lambda s: int(s[1:]))
        self.K = len(self.vars)
        self.vax = {v: i for i, v in enumerate(self.vars)}
        # structural fingerprint (DC_fp): polarity profile, antecedent share, mean depth, quantified-slot share
        fp = {}
        for p in self.preds:
            os_ = [o for o in occ if o["name"] == p]
            n = max(1, len(os_))
            fp[p] = np.array([sum(o["pol"] > 0 for o in os_) / n, sum(o["pol"] < 0 for o in os_) / n,
                              sum(o["ante"] for o in os_) / n, sum(o["depth"] for o in os_) / n / 10.0,
                              sum(t[0] == "var" for o in os_ for t in o["args"]) / max(1, sum(len(o["args"]) for o in os_)),
                              self.n_occ[p] / max(1, len(occ)), self.first[p]])
        self.fp = fp
        self.n_quant = sum(1 for _ in _quants(self.ast))
        self._models = {}

    def quant_profile(self) -> tuple:
        return tuple(sorted(Counter(q for q in _quants(self.ast)).items()))


def _bound_vars(ast):
    if ast[0] in ("forall", "exists"):
        yield ast[1]
        yield from _bound_vars(ast[2])
    elif ast[0] == "not":
        yield from _bound_vars(ast[1])
    elif ast[0] in SYM:
        yield from _bound_vars(ast[1])
        yield from _bound_vars(ast[2])


def _quants(ast):
    if ast[0] in ("forall", "exists"):
        yield ast[0]
        yield from _quants(ast[2])
    elif ast[0] == "not":
        yield from _quants(ast[1])
    elif ast[0] in SYM:
        yield from _quants(ast[1])
        yield from _quants(ast[2])


# ============================================================================== vectorised evaluator
class Batch:
    """S structures over one domain size n: T[name] bool array (S,)+(n,)*arity; C[const] int array (S,)."""

    def __init__(self, n: int, S: int):
        self.n, self.S = n, S
        self.T: dict[str, np.ndarray] = {}
        self.C: dict[str, np.ndarray] = {}
        self._idx = {}

    def sidx(self, K):
        key = ("s", K)
        if key not in self._idx:
            self._idx[key] = np.arange(self.S).reshape((self.S,) + (1,) * K)
        return self._idx[key]

    def vidx(self, K, j):
        key = ("v", K, j)
        if key not in self._idx:
            shp = [1] * (K + 1)
            shp[j + 1] = self.n
            self._idx[key] = np.arange(self.n).reshape(shp)
        return self._idx[key]


def evaluate(F: Formula, B: Batch, nm: dict | None = None, cm: dict | None = None) -> np.ndarray:
    """Truth value of closed formula F on every structure of batch B. nm/cm rename predicates/constants
    (name -> key in B.T / B.C)."""
    nm = nm or {}
    cm = cm or {}
    K = F.K

    def term(t):
        if t[0] == "var":
            return B.vidx(K, F.vax[t[1]])
        return B.C[cm.get(t[1], t[1])].reshape((B.S,) + (1,) * K)

    def ev(a):
        op = a[0]
        if op == "atom":
            T = B.T[nm.get(a[1], a[1])]
            if not a[2]:
                return T.reshape((B.S,) + (1,) * K)
            return T[(B.sidx(K),) + tuple(term(t) for t in a[2])]
        if op == "eq":
            r = term(a[1]) == term(a[2])
            return np.logical_or(r, np.zeros((B.S,) + (1,) * K, bool))
        if op == "not":
            return ~ev(a[1])
        if op == "and":
            return ev(a[1]) & ev(a[2])
        if op == "or":
            return ev(a[1]) | ev(a[2])
        if op == "imp":
            return (~ev(a[1])) | ev(a[2])
        if op == "iff":
            return ev(a[1]) == ev(a[2])
        if op == "xor":
            return ev(a[1]) != ev(a[2])
        if op in ("forall", "exists"):
            x = ev(a[2])
            ax = 1 + F.vax[a[1]]
            if x.shape[ax] == 1:
                return x
            return x.all(axis=ax, keepdims=True) if op == "forall" else x.any(axis=ax, keepdims=True)
        raise ValueError(op)
    r = ev(F.ast)
    return np.broadcast_to(r, (B.S,) + r.shape[1:]).reshape(B.S, -1)[:, 0]


def random_batch(n: int, S: int, preds: dict, consts, rng: np.random.Generator) -> Batch:
    B = Batch(n, S)
    dens = rng.choice([0.2, 0.5, 0.8], size=S)
    for p, a in preds.items():
        B.T[p] = rng.random((S,) + (n,) * a) < dens.reshape((S,) + (1,) * a)
    for c in consts:
        B.C[c] = rng.integers(0, n, size=S)
    return B


def add_random(B: Batch, preds: dict, consts, rng: np.random.Generator) -> None:
    for p, a in preds.items():
        if p not in B.T:
            B.T[p] = rng.random((B.S,) + (B.n,) * a) < 0.5
    for c in consts:
        if c not in B.C:
            B.C[c] = rng.integers(0, B.n, size=B.S)


def solver_structures(F: Formula, n: int, k: int, positive: bool, seed: int, timeout_ms: int = 3000) -> list[dict]:
    """Up to k models of F (positive) or of ¬F over domain n via vendor grounding; returns [{T:{p:arr}, C:{c:int}}]."""
    cvars = {c: z3.Int(f"c#{c}") for c in F.consts}
    g = _Grounder(n, None, cvars)
    try:
        expr = g.g(F.ast, {})
    except (z3.Z3Exception, RecursionError):
        return []
    s = z3.Solver()
    s.set("timeout", timeout_ms)
    s.set("random_seed", seed)
    for v in cvars.values():
        s.add(v >= 0, v < n)
    s.add(expr if positive else z3.Not(expr))
    out = []
    atoms = list(g.atoms.items())
    rng = random.Random(seed)
    for _ in range(k):
        try:
            r = s.check()
        except z3.Z3Exception:
            break
        if r != z3.sat:
            break
        m = s.model()
        T = {p: np.zeros((n,) * a, bool) for p, a in F.preds.items()}
        vals = []
        for (name, args), b in atoms:
            v = z3.is_true(m.eval(b, model_completion=True))
            vals.append((b, v))
            if name in T and v:
                T[name][args] = True
        C = {c: m.eval(cv, model_completion=True).as_long() for c, cv in cvars.items()}
        out.append({"T": T, "C": C})
        # block a random subset of the assignment for diversity
        if not vals:
            break
        sub = rng.sample(vals, max(1, len(vals) // 3))
        s.add(z3.Or(*[b != z3.BoolVal(v) for b, v in sub]))
    return out


def stack_structs(structs: list[dict], n: int, preds: dict, consts) -> Batch | None:
    if not structs:
        return None
    B = Batch(n, len(structs))
    for p, a in preds.items():
        B.T[p] = np.stack([s["T"][p] if p in s["T"] else np.zeros((n,) * a, bool) for s in structs])
    for c in consts:
        B.C[c] = np.array([s["C"].get(c, 0) for s in structs])
    return B


def formula_structs(F: Formula, k: int, seed: int) -> dict:
    """cached per formula: {n: {"pos": [...], "neg": [...]}} for n in (2, 3)."""
    key = (k, seed)
    if key not in F._models:
        F._models[key] = {n: {"pos": solver_structures(F, n, k, True, seed + n),
                              "neg": solver_structures(F, n, k, False, seed + 10 + n)} for n in (2, 3)}
    return F._models[key]


# ============================================================================== maps
def _blocks(preds: dict) -> dict[int, list[str]]:
    g = defaultdict(list)
    for p, a in preds.items():
        g[a].append(p)
    return g


def _order_key(F: Formula, p: str):
    return (-F.n_occ.get(p, 0), F.first.get(p, 0.0), p)  # name only as the final deterministic tie-break


def _cost(A: Formula, B: Formula, a: str, b: str, order: str) -> float:
    if order == "fp":
        return float(np.abs(A.fp[a] - B.fp[b]).sum())
    return abs(A.n_occ[a] - B.n_occ[b]) / max(A.n_occ[a], B.n_occ[b], 1) + abs(A.first[a] - B.first[b])


def base_assignment(A: Formula, B: Formula, order: str) -> tuple[dict, dict]:
    """per arity block: min-cost (Hungarian) assignment B-pred -> A-pred; also constants."""
    from scipy.optimize import linear_sum_assignment
    ga, gb = _blocks(A.preds), _blocks(B.preds)
    m = {}
    for ar, bl in gb.items():
        al = ga.get(ar, [])
        if not al:
            continue
        bl = sorted(bl, key=lambda p: _order_key(B, p))
        al = sorted(al, key=lambda p: _order_key(A, p))
        cm = np.array([[_cost(A, B, a, b, order) for a in al] for b in bl])
        r, c = linear_sum_assignment(cm)
        for i, j in zip(r, c):
            m[bl[i]] = al[j]
    cmap = {}
    ca = sorted(A.consts, key=lambda c: (-A.c_occ[c], A.cfirst[c], c))
    cb = sorted(B.consts, key=lambda c: (-B.c_occ[c], B.cfirst[c], c))
    for x, y in zip(cb, ca):
        cmap[x] = y
    return m, cmap


def _coverage(B: Formula, m: dict) -> float:
    tot = sum(B.n_occ.values())
    return sum(B.n_occ[b] for b in m) / tot if tot else 1.0


def arity_profile(F: Formula) -> tuple:
    return tuple(sorted(Counter(F.preds.values()).items())) + (("c", len(F.consts)),)


def l1_maps(A: Formula, B: Formula, cap: int, order: str):
    """bijections (B -> A) of equal arity profiles. Exhaustive (sorted by distance from the base assignment) when the
    total is <= cap, otherwise the k-displacement neighbourhoods of the base assignment in increasing k."""
    if arity_profile(A) != arity_profile(B):
        return
    base, cbase = base_assignment(A, B, order)
    gb = _blocks(B.preds)
    blocks = [sorted(bl, key=lambda p: _order_key(B, p)) for _, bl in sorted(gb.items())]
    total = math.prod(math.factorial(len(b)) for b in blocks) * math.factorial(len(B.consts))
    cb = sorted(cbase)
    seen = set()
    n_out = 0

    def emit(m, cm):
        nonlocal n_out
        key = tuple(sorted(m.items())) + tuple(sorted(cm.items()))
        if key in seen:
            return False
        seen.add(key)
        n_out += 1
        return True

    if total <= cap:
        allm = []
        for perms in itertools.product(*[itertools.permutations([base[b] for b in bl]) for bl in blocks]):
            m = {}
            for bl, perm in zip(blocks, perms):
                m.update(dict(zip(bl, perm)))
            d = sum(m[b] != base[b] for b in m)
            allm.append((d, m))
        allm.sort(key=lambda x: x[0])
        cperms = [dict(zip(cb, p)) for p in itertools.permutations([cbase[c] for c in cb])] or [{}]
        cperms.sort(key=lambda cm: sum(cm[c] != cbase[c] for c in cm))
        for d, m in allm:
            for cm in cperms:
                if emit(m, cm):
                    yield m, cm
        return
    # neighbourhoods: transpositions, then 3-cycles, ... within blocks (constants kept at base)
    if emit(dict(base), dict(cbase)):
        yield dict(base), dict(cbase)
    flat = [(bi, b) for bi, bl in enumerate(blocks) for b in bl]
    for k in range(2, 8):
        for combo in itertools.combinations(range(len(flat)), k):
            bis = {flat[i][0] for i in combo}
            if len(bis) != 1:
                continue
            names = [flat[i][1] for i in combo]
            imgs = [base[b] for b in names]
            for perm in itertools.permutations(imgs):
                if any(p == base[b] for p, b in zip(perm, names)):
                    continue  # derangements only (exact k-displacement)
                m = dict(base)
                m.update(dict(zip(names, perm)))
                if emit(m, dict(cbase)):
                    yield m, dict(cbase)
                if n_out >= cap:
                    return


def l2_maps(A: Formula, B: Formula, cap: int, min_cov: float, order: str):
    """partial injective arity-preserving maps B -> A covering >= min_cov of B's predicate occurrences."""
    base, cbase = base_assignment(A, B, order)
    seen = set()
    n = 0

    def ok(m):
        return _coverage(B, m) >= min_cov - 1e-9

    def emit(m, cm):
        nonlocal n
        key = tuple(sorted(m.items())) + tuple(sorted(cm.items()))
        if key in seen or not ok(m):
            return False
        seen.add(key)
        n += 1
        return True

    if emit(dict(base), dict(cbase)):
        yield dict(base), dict(cbase)
    bs = sorted(B.preds, key=lambda p: _order_key(B, p))
    ga = _blocks(A.preds)
    # (i) single re-assignments (swap if the target is used)
    for b in bs:
        for a in sorted(ga.get(B.preds[b], []), key=lambda p: _order_key(A, p)):
            if base.get(b) == a:
                continue
            m = dict(base)
            inv = {v: k for k, v in m.items()}
            if a in inv:
                other = inv[a]
                if b in m:
                    m[other] = m[b]
                else:
                    del m[other]
            m[b] = a
            if emit(m, dict(cbase)):
                yield m, dict(cbase)
            if n >= cap:
                return
    # (ii) drop one / two mapped predicates (they become fresh)
    mapped = [b for b in bs if b in base]
    for k in (1, 2):
        for drop in itertools.combinations(mapped, k):
            m = {b: a for b, a in base.items() if b not in drop}
            if emit(m, dict(cbase)):
                yield m, dict(cbase)
            if n >= cap:
                return
    # (iii) pairs of re-assignments
    singles = []
    for b in bs:
        for a in sorted(ga.get(B.preds[b], []), key=lambda p: _order_key(A, p)):
            if base.get(b) != a:
                singles.append((b, a))
    for (b1, a1), (b2, a2) in itertools.combinations(singles, 2):
        if b1 == b2 or a1 == a2:
            continue
        m = {b: a for b, a in base.items() if a not in (a1, a2)}
        m[b1], m[b2] = a1, a2
        if emit(m, dict(cbase)):
            yield m, dict(cbase)
        if n >= cap:
            return


def l3_defsets(A: Formula, B: Formula, base: dict, cap: int, max_defs: int, max_lits: int):
    """definition sets {b: [(a, slots, False), ...]}: <= max_defs B-predicates, each defined as a conjunction of
    2..max_lits POSITIVE literals over A-predicates that are NOT in the image of the remaining map (A-predicates
    unmatched once the defined B-predicates are removed from the base map), each A-predicate used at most once per
    set. Rationale (fixed before any label, from the T0 toy tests): negated literals would let a definition absorb an
    exception ('Bird := Bird ∧ ¬Penguin'), and literals over still-mapped predicates let it absorb the consequent;
    both manufacture agreement. Positive granularity (TallMan := Tall ∧ Man) is kept; it is formula-only
    indistinguishable from a dropped positive restrictor (documented identifiability limit)."""
    bs = sorted(B.preds, key=lambda p: _order_key(B, p))
    targets = [b for b in bs if b not in base] + [b for b in bs if b in base]
    out = []

    def lits(b, free_a):
        ar = B.preds[b]
        L = []
        for a in free_a:
            ka = A.preds[a]
            if 0 < ka <= ar or (ka == 0 and ar == 0):
                for slots in itertools.permutations(range(ar), ka):
                    L.append((a, slots))
        return L

    def defs_for(b, free_a):
        L = lits(b, free_a)
        res = []
        for k in range(2, max_lits + 1):
            for combo in itertools.combinations(L, k):
                if len({c[0] for c in combo}) < k:
                    continue
                if not set(range(B.preds[b])) <= {s for c in combo for s in c[1]}:
                    continue  # every argument slot of b must be constrained
                res.append([(a, sl, False) for a, sl in combo])
        return res

    for b in targets:
        m = {x: a for x, a in base.items() if x != b}
        free_a = [a for a in sorted(A.preds, key=lambda p: _order_key(A, p)) if a not in set(m.values())]
        for d in defs_for(b, free_a):
            out.append({b: d})
            if len(out) >= cap:
                return out
    if max_defs >= 2:
        for b1, b2 in itertools.combinations(targets, 2):
            m = {x: a for x, a in base.items() if x not in (b1, b2)}
            free_a = [a for a in sorted(A.preds, key=lambda p: _order_key(A, p)) if a not in set(m.values())]
            for d1 in defs_for(b1, free_a):
                used = {x[0] for x in d1}
                for d2 in defs_for(b2, [a for a in free_a if a not in used]):
                    out.append({b1: d1, b2: d2})
                    if len(out) >= cap:
                        return out
    return out


# ============================================================================== AST transforms for z3
def rename_ast(ast, pm: dict, cm: dict, fresh_prefix: str = "~"):
    op = ast[0]
    if op in ("forall", "exists"):
        return (op, "B" + ast[1], rename_ast(ast[2], pm, cm, fresh_prefix))
    if op == "not":
        return ("not", rename_ast(ast[1], pm, cm, fresh_prefix))
    if op in SYM:
        return (op, rename_ast(ast[1], pm, cm, fresh_prefix), rename_ast(ast[2], pm, cm, fresh_prefix))

    def tt(t):
        if t[0] == "var":
            return ("var", "B" + t[1])
        return ("const", cm.get(t[1], fresh_prefix + t[1]))
    if op == "atom":
        return ("atom", pm.get(ast[1], fresh_prefix + ast[1]), tuple(tt(t) for t in ast[2]))
    if op == "eq":
        return ("eq", tt(ast[1]), tt(ast[2]))
    raise ValueError(op)


def substitute_defs(ast, defs: dict):
    """replace atoms of defined B-predicates (already renamed to '~b' or their image) by literal conjunctions.
    defs: {renamed_name: [(a, slots, neg), ...]}"""
    op = ast[0]
    if op in ("forall", "exists"):
        return (op, ast[1], substitute_defs(ast[2], defs))
    if op == "not":
        return ("not", substitute_defs(ast[1], defs))
    if op in SYM:
        return (op, substitute_defs(ast[1], defs), substitute_defs(ast[2], defs))
    if op == "atom" and ast[1] in defs:
        lits = []
        for a, slots, neg in defs[ast[1]]:
            at = ("atom", a, tuple(ast[2][s] for s in slots))
            lits.append(("not", at) if neg else at)
        r = lits[0]
        for l in lits[1:]:
            r = ("and", r, l)
        return r
    return ast


def z3_entails(F, G, preds: dict, consts: list, timeout_ms: int) -> str:
    """unbounded check F ⊨ G over an uninterpreted sort (vendor fol_equiv.unbounded_equiv construction)."""
    U = z3.DeclareSort("U")
    funcs = {p: (z3.Function(f"P_{p}", *([U] * a), z3.BoolSort()) if a > 0 else z3.Bool(f"P_{p}")) for p, a in preds.items()}
    cs = {c: z3.Const(f"K_{c}", U) for c in consts}

    def tr(node, env):
        op = node[0]
        if op == "atom":
            args = [env[t[1]] if t[0] == "var" else cs[t[1]] for t in node[2]]
            f = funcs[node[1]]
            return f(*args) if args else f
        if op == "eq":
            a = [env[t[1]] if t[0] == "var" else cs[t[1]] for t in node[1:]]
            return a[0] == a[1]
        if op == "not":
            return z3.Not(tr(node[1], env))
        if op in ("and", "or", "imp", "iff", "xor"):
            a, b = tr(node[1], env), tr(node[2], env)
            if op == "iff":
                return a == b
            return {"and": z3.And, "or": z3.Or, "imp": z3.Implies, "xor": z3.Xor}[op](a, b)
        if op in ("forall", "exists"):
            v = z3.Const(f"v_{node[1]}_{id(node)}", U)
            body = tr(node[2], {**env, node[1]: v})
            return z3.ForAll([v], body) if op == "forall" else z3.Exists([v], body)
        raise ValueError(op)
    try:
        s = z3.Solver()
        s.set("timeout", timeout_ms)
        s.add(tr(F, {}), z3.Not(tr(G, {})))
        r = s.check()
        return "unsat" if r == z3.unsat else ("sat" if r == z3.sat else "unknown")
    except z3.Z3Exception:
        return "unknown"


def _sig(ast):
    return signature(ast)


# ============================================================================== pair checking
class PairCtx:
    """Structures for one ordered pair (A, B): A-side batches (models/countermodels of A + random, with fresh tensors
    for every B symbol) and B-side batches (models/countermodels of B, with random tensors for A symbols)."""

    def __init__(self, A: Formula, B: Formula, limits: dict, seed: int = 0):
        self.A, self.B, self.L = A, B, limits
        rng = np.random.default_rng(seed)
        fresh_b = {"~" + b: a for b, a in B.preds.items()}
        fresh_bc = ["~" + c for c in B.consts]
        fresh_a = {"~" + a: k for a, k in A.preds.items()}
        fresh_ac = ["~" + c for c in A.consts]
        k = limits["n_models"]
        sa, sb = formula_structs(A, k, seed), formula_structs(B, k, seed + 1)
        self.abatches, self.bbatches = [], []
        for n in (2, 3):
            parts = []
            for kind in ("pos", "neg"):
                bt = stack_structs(sa[n][kind], n, A.preds, A.consts)
                if bt is not None:
                    parts.append(bt)
            rb = random_batch(n, limits["n_random"] // 2, A.preds, A.consts, rng)
            parts.append(rb)
            for bt in parts:
                add_random(bt, fresh_b, fresh_bc, rng)
                self.abatches.append(bt)
            for kind in ("pos", "neg"):
                bt = stack_structs(sb[n][kind], n, B.preds, B.consts)
                if bt is not None:
                    add_random(bt, fresh_a, fresh_ac, rng)
                    self.bbatches.append(bt)
        self.aval = [evaluate(A, bt) for bt in self.abatches]
        self.bval = [evaluate(B, bt) for bt in self.bbatches]
        self.rng = rng

    def filter(self, m: dict, cm: dict, defs: dict | None = None) -> tuple[bool, bool, bool]:
        """(A⊨B alive, B⊨A alive, joint model witnessed) under map m (B->A), constant map cm, optional L3 defs."""
        A, B = self.A, self.B
        nmB = {b: m.get(b, "~" + b) for b in B.preds}
        cmB = {c: cm.get(c, "~" + c) for c in B.consts}
        f2g = g2f = True
        joint = False
        for bt, av in zip(self.abatches, self.aval):
            if defs:
                for b, lits in defs.items():
                    key = "#def:" + b + ":" + repr(lits)
                    if key not in bt.T:
                        ar = B.preds[b]
                        acc = np.ones((bt.S,) + (bt.n,) * ar, bool)
                        for a, slots, neg in lits:
                            Ta = bt.T[a]
                            # place A-literal axes at the given B slots
                            idx = [np.arange(bt.S).reshape((bt.S,) + (1,) * ar)]
                            for s in slots:
                                shp = [1] * (ar + 1)
                                shp[s + 1] = bt.n
                                idx.append(np.arange(bt.n).reshape(shp))
                            v = Ta[tuple(idx)] if slots else Ta.reshape((bt.S,) + (1,) * ar)
                            acc = acc & (~v if neg else v)
                        bt.T[key] = acc
                    nmB[b] = key
            bv = evaluate(B, bt, nmB, cmB)
            if (av & ~bv).any():
                f2g = False
            if (bv & ~av).any():
                g2f = False
            if (av & bv).any():
                joint = True
            if not f2g and not g2f and joint:
                return f2g, g2f, joint
        if not defs:
            inv = {a: b for b, a in m.items()}
            cinv = {a: b for b, a in cm.items()}
            nmA = {a: inv.get(a, "~" + a) for a in A.preds}
            cmA = {c: cinv.get(c, "~" + c) for c in A.consts}
            for bt, bv in zip(self.bbatches, self.bval):
                av = evaluate(A, bt, nmA, cmA)
                if (av & ~bv).any():
                    f2g = False
                if (bv & ~av).any():
                    g2f = False
                if (av & bv).any():
                    joint = True
                if not f2g and not g2f and joint:
                    break
        return f2g, g2f, joint

    def z3_decide(self, m: dict, cm: dict, defs: dict | None, f2g: bool, g2f: bool, joint: bool,
                  deadline: float) -> str:
        A, B, L = self.A, self.B, self.L
        Bp = rename_ast(B.ast, m, cm)
        if defs:
            Bp = substitute_defs(Bp, {m.get(b, "~" + b): lits for b, lits in defs.items()})
        pa, ca = _sig(A.ast)
        pb, cb = _sig(Bp)
        preds = {**pa, **pb}
        consts = sorted(set(ca) | set(cb))
        ns = L["domains"]
        tmo = L["z3_timeout_ms"]
        res = {}
        for key, alive, mode in (("f2g", f2g, "f2g"), ("g2f", g2f, "g2f")):
            if not alive:
                res[key] = False
                continue
            if time.time() > deadline:
                return "UNKNOWN"
            r, _ = bounded_check(A.ast, Bp, consts, {}, mode, ns=ns, timeout_ms=tmo, deadline=deadline)
            if r == "countermodel":
                res[key] = False
            elif r == "timeout":
                return "UNKNOWN"
            else:
                ub = z3_entails(A.ast, Bp, preds, consts, tmo) if mode == "f2g" else z3_entails(Bp, A.ast, preds, consts, tmo)
                res[key] = ub != "sat"
        if res["f2g"] and res["g2f"]:
            return "EQUIV"
        if res["f2g"]:
            return "STRONGER"
        if res["g2f"]:
            return "WEAKER"
        if joint:
            return "COMPATIBLE-INCOMPARABLE"
        # joint satisfiability check (bounded): SAT(A ∧ B') ?
        for n in ns:
            if time.time() > deadline:
                return "UNKNOWN"
            cv = {c: z3.Int(f"c#{c}") for c in consts}
            s = z3.Solver()
            s.set("timeout", tmo)
            try:
                fa = _Grounder(n, None, cv).g(A.ast, {})
                fb = _Grounder(n, None, cv).g(Bp, {})
            except (z3.Z3Exception, RecursionError):
                return "UNKNOWN"
            for v in cv.values():
                s.add(v >= 0, v < n)
            s.add(fa, fb)
            r = s.check()
            if r == z3.sat:
                return "COMPATIBLE-INCOMPARABLE"
            if r == z3.unknown:
                return "UNKNOWN"
        return "CONTRADICTORY"


def _better(r1: str, r2: str | None) -> bool:
    if r2 is None or r2 in ("UNKNOWN",):
        return r1 not in ("UNKNOWN",)
    return REL_ORDER.get(r1, 0) > REL_ORDER.get(r2, 0)


def align_pair(A: Formula, B: Formula, limits: dict | None = None):
    """MEASURES: the lexical-free vocabulary correspondences under which B can be read in A's vocabulary.
    Yields (level, map B->A, const map, defs) in level order L1 -> L2 -> L3 (defs only at L3)."""
    L = {**DEFAULT_LIMITS, **(limits or {})}
    order = L["order"]
    for m, cm in l1_maps(A, B, L["l1_cap"], order):
        yield 1, m, cm, None
    for m, cm in l2_maps(A, B, L["l2_cap"], L["l2_min_cov"], order):
        yield 2, m, cm, None
    base, cbase = base_assignment(A, B, order)
    if _coverage(B, base) < L["l2_min_cov"] - 1e-9:
        return  # L3 builds on an L2-admissible base map; otherwise the pair is UNALIGNABLE
    for d in l3_defsets(A, B, base, L["l3_cap"], L["l3_max_defs"], L["l3_max_lits"]):
        m = {b: a for b, a in base.items() if b not in d}
        yield 3, m, dict(cbase), d


def _search(A: Formula, B: Formula, L: dict, deadline: float, seed: int, levels=(1, 2, 3)) -> dict:
    ctx = PairCtx(A, B, L, seed)
    best = {"relation": None, "level": None, "map": None, "cmap": None, "defs": None}
    best12 = {"relation": None, "level": None, "map": None}
    n_maps = Counter()
    n_z3 = 0
    any_map = False
    all_unknown = True
    timed_out = False
    tried_keys = set()
    for level, m, cm, defs in align_pair(A, B, L):
        if level not in levels:
            continue
        if time.time() > deadline:
            timed_out = True
            break
        any_map = True
        n_maps[level] += 1
        f2g, g2f, joint = ctx.filter(m, cm, defs)
        cand = "EQUIV" if (f2g and g2f) else ("STRONGER" if f2g else ("WEAKER" if g2f else
                                                                    ("COMPATIBLE-INCOMPARABLE" if joint else "CONTRADICTORY?")))
        # only call z3 when the filter outcome could improve on the current best
        opt = {"EQUIV": 4, "STRONGER": 3, "WEAKER": 3, "COMPATIBLE-INCOMPARABLE": 2, "CONTRADICTORY?": 1}[cand]
        if best["relation"] is not None and opt <= REL_ORDER.get(best["relation"], 0):
            all_unknown = False if best["relation"] else all_unknown
            continue
        if cand == "COMPATIBLE-INCOMPARABLE":
            rel = cand  # witnessed joint model and both directions refuted: sound without z3
        else:
            key = (level, tuple(sorted(m.items())), repr(defs), cand)
            if key in tried_keys:
                continue
            tried_keys.add(key)
            if n_z3 >= L["max_z3_maps"]:
                continue
            n_z3 += 1
            rel = ctx.z3_decide(m, cm, defs, f2g, g2f, joint, deadline)
        if rel != "UNKNOWN":
            all_unknown = False
        if level in (1, 2) and _better(rel, best12["relation"]):
            best12 = {"relation": rel, "level": level, "map": dict(m)}
        if _better(rel, best["relation"]):
            best = {"relation": rel, "level": level, "map": dict(m), "cmap": dict(cm),
                    "defs": {k: [list(x) for x in v] for k, v in defs.items()} if defs else None}
            if rel == "EQUIV":
                break
    if not any_map:
        best["relation"] = "UNALIGNABLE"
    elif best["relation"] is None:
        best["relation"] = "UNKNOWN"
    b12 = best12 if best12["relation"] is not None else None
    any12 = n_maps.get(1, 0) + n_maps.get(2, 0) > 0
    best.update(n_maps=dict(n_maps), n_z3=n_z3, timed_out=timed_out,
                relation_l12=(b12["relation"] if b12 else ("UNALIGNABLE" if not any12 and not timed_out else "UNKNOWN")),
                level_l12=b12["level"] if b12 else None, map_l12=b12["map"] if b12 else None)
    return best


def pair_relation(fol_a: str | Formula, fol_b: str | Formula, limits: dict | None = None, seed: int = 0) -> dict:
    """MEASURES: the logical order between A and B read in A's vocabulary under the most informative lexical-free
    alignment: EQUIV / STRONGER (A ⊨ B only) / WEAKER (B ⊨ A only) / COMPATIBLE-INCOMPARABLE / CONTRADICTORY /
    UNALIGNABLE (no arity-preserving map) / UNKNOWN (every map timed out). L3 is tried in both directions."""
    L = {**DEFAULT_LIMITS, **(limits or {})}
    t0 = time.time()
    A = fol_a if isinstance(fol_a, Formula) else Formula(fol_a)
    B = fol_b if isinstance(fol_b, Formula) else Formula(fol_b)
    if not (A.ok and B.ok):
        return {"relation": "UNPARSEABLE", "level": None, "seconds": 0.0}
    deadline = t0 + L["pair_seconds"]
    # L1 + L2 + L3 (B defined over A)
    res = _search(A, B, L, deadline, seed)
    res["direction"] = "B_in_A"
    if res["relation"] != "EQUIV" and time.time() < deadline:
        # L3 reverse: A's predicates defined over B's vocabulary (granularity in the other direction)
        r2 = _search(B, A, L, deadline, seed + 7, levels=(3,))
        if r2["relation"] not in ("UNKNOWN", "UNALIGNABLE", None):
            rel2 = INVERSE.get(r2["relation"], r2["relation"])
            if _better(rel2, res["relation"] if res["relation"] not in ("UNALIGNABLE",) else None):
                r2["relation"] = rel2
                r2["direction"] = "A_in_B"
                r2["n_maps_fwd"] = res.get("n_maps")
                for k in ("relation_l12", "level_l12", "map_l12"):
                    r2[k] = res.get(k)
                res = r2
    res["seconds"] = round(time.time() - t0, 3)
    return res

source_files.vendor/ds/fol_parse.py:
"""Tolerant first-order-logic parser / printer for NL->FOL outputs.

Extended from the GEN_HYPO feasibility prototype
(iter_1/gen_hypo/claude_agent/feasibility/monotonicity_profile.py, Pratt parser).

Accepted syntax
- Quantifiers: ∀ ∃ and ASCII `forall` `exists` (also `all`/`some` when followed by a variable
  and a formula); multi-binders `∀x ∀y`, `∀x,y`, `∀x y`, `∀x.` `∀x:` `(∀x)`.
- Connectives: ¬ ~ ! not | ∧ & and | ∨ | or | → -> => ⇒ ⊃ | ↔ <-> <=> ⇔ ≡ | ⊕ xor ^ ⊻.
- Equality `=`, `≠`, `!=`. Predicates in CamelCase or snake_case; 0-ary propositions.
- Constants: any argument identifier that is not bound by an enclosing quantifier.
- Unsupported (parse error): function terms, ∈ ⊆ < > and arithmetic.

AST (hashable tuples)
  ('forall', var, body) ('exists', var, body) ('not', a) ('and', a, b) ('or', a, b)
  ('imp', a, b) ('iff', a, b) ('xor', a, b) ('atom', name, (term, ...)) ('eq', t1, t2)
  term = ('var', name) | ('const', name)

Scope policy: a quantifier followed by '(' scopes over that group (FOLIO convention). If the
result leaves variables free that a quantifier binds elsewhere, the formula is re-parsed with
WIDE scope (quantifier body extends to the right as far as possible); remaining free
single-letter variables are universally closed. Both repairs are reported in `ParseResult.notes`.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field

QUANT = {"∀": "forall", "∃": "exists", "forall": "forall", "exists": "exists", "exist": "exists",
         "all": "forall", "some": "exists", "∀∀": "forall"}
NOT_TOK = {"¬", "~", "!", "not", "∼", "￢"}
BIN = {
    "∧": "and", "&": "and", "&&": "and", "and": "and", "/\\": "and", "⋀": "and",
    "∨": "or", "|": "or", "||": "or", "or": "or", "\\/": "or", "⋁": "or",
    "→": "imp", "->": "imp", "=>": "imp", "⇒": "imp", "⊃": "imp", "⟶": "imp", "implies": "imp",
    "↔": "iff", "<->": "iff", "<=>": "iff", "⇔": "iff", "≡": "iff", "⟷": "iff", "iff": "iff",
    "⊕": "xor", "xor": "xor", "⊻": "xor", "^": "and",  # ASCII ^ is read as conjunction (∧ look-alike)
}
PREC = {"iff": 1, "xor": 1, "imp": 2, "or": 3, "and": 4}
SYM = {"and": "∧", "or": "∨", "imp": "→", "iff": "↔", "xor": "⊕"}

TOK_RE = re.compile(
    r"\s*(<->|<=>|->|=>|&&|\|\||/\\|\\/|!=|≠|∀|∃|¬|∧|∨|→|↔|⊕|⇒|⇔|⊃|≡|⊻|⟶|⟷|⋀|⋁|∼|￢|"
    r"[~!&|^()\[\],.:=]|∈|⊆|⊂|<|>|≤|≥|\+|\*|/|-|"
    r"\"[^\"]{0,60}\"|[0-9]+\.[0-9]+[A-Za-z0-9_%]*|"
    r"[A-Za-z0-9_À-ɏ]+(?:['\-][A-Za-z0-9_À-ɏ]+)*)"
)
VARLIKE = re.compile(r"^[a-z][0-9]{0,2}'*$")  # x, y1, z12, x' ; NOT yr2028 / p1080 (constants)


class FOLParseError(ValueError):
    pass


@dataclass
class ParseResult:
    ast: tuple | None
    ok: bool
    error: str = ""
    notes: list[str] = field(default_factory=list)
    text: str = ""


def tokenize(s: str) -> list[str]:
    out, pos = [], 0
    s = s.strip()
    while pos < len(s):
        m = TOK_RE.match(s, pos)
        if not m or m.end() == pos:
            raise FOLParseError(f"cannot tokenize at {s[pos:pos + 20]!r}")
        out.append(m.group(1))
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    return out


def _is_ident(t: str | None) -> bool:
    return t is not None and bool(re.match(r"^[\"A-Za-z0-9_À-ɏ]", t)) \
        and t.lower() not in ("and", "or", "not", "xor", "implies", "iff") and t not in QUANT


class _Parser:
    def __init__(self, toks: list[str], wide: bool):
        self.t, self.i, self.wide = toks, 0, wide

    def peek(self, k: int = 0):
        j = self.i + k
        return self.t[j] if j < len(self.t) else None

    def eat(self, x: str | None = None) -> str:
        tok = self.peek()
        if tok is None:
            raise FOLParseError(f"unexpected end (expected {x})" if x else "unexpected end")
        if x is not None and tok != x:
            raise FOLParseError(f"expected {x!r} got {tok!r}")
        self.i += 1
        return tok

    def binop(self) -> str | None:
        tok = self.peek()
        if tok is None:
            return None
        return BIN.get(tok) or BIN.get(tok.lower()) if (tok in BIN or tok.lower() in BIN) else None

    def parse_formula(self, minp: int = 1) -> tuple:
        lhs = self.unary()
        while True:
            op = self.binop()
            if op is None or PREC[op] < minp:
                break
            self.eat()
            p = PREC[op]
            rhs = self.parse_formula(p if op == "imp" else p + 1)
            lhs = (op, lhs, rhs)
        return lhs

    def is_quant_start(self) -> bool:
        tok = self.peek()
        if tok in ("∀", "∃"):
            return True
        if tok is not None and tok.lower() in ("forall", "exists", "exist"):
            return True
        if tok is not None and tok.lower() in ("all", "some"):
            nxt, nxt2 = self.peek(1), self.peek(2)
            return nxt is not None and bool(VARLIKE.match(nxt)) and nxt2 not in (")", ",", None)
        return False

    def binders(self) -> list[str]:
        vars_ = []
        while True:
            tok = self.peek()
            if tok is None:
                raise FOLParseError("quantifier without variable")
            if not _is_ident(tok):
                raise FOLParseError(f"bad quantified variable {tok!r}")
            self.eat()
            vars_.append(tok)
            nxt = self.peek()
            if nxt == ",":
                # ∀x,y (...)  -- only if an identifier that is not a predicate call follows
                call_like = self.peek(2) == "(" and _is_ident(self.peek(3)) and self.peek(4) in (",", ")")
                if _is_ident(self.peek(1)) and (self.peek(2) != "(" or (VARLIKE.match(self.peek(1)) and not call_like)):
                    self.eat(",")
                    continue
                self.eat(",")
                break
            if nxt in (".", ":"):
                self.eat()
                break
            # ∀x y (...)  : a following lowercase var-like identifier not followed by '('
            if _is_ident(nxt) and VARLIKE.match(nxt) and self.peek(1) is not None \
                    and self.peek(1) not in BIN and self.peek(1) not in (")", ",", "=", "≠", "!="):
                looks_call = self.peek(1) == "(" and _is_ident(self.peek(2)) and self.peek(3) in (",", ")")
                if not looks_call:
                    continue
            break
        return vars_

    def unary(self) -> tuple:
        tok = self.peek()
        if tok is None:
            raise FOLParseError("unexpected end of formula")
        if self.is_quant_start():
            q = QUANT[tok.lower()] if tok.lower() in QUANT else QUANT[tok]
            self.eat()
            if self.peek() == "(" and _is_ident(self.peek(1)) and self.peek(2) == ")" :
                # ∀(x) body
                self.eat("(")
                vars_ = [self.eat()]
                self.eat(")")
            else:
                vars_ = self.binders()
            body = self.quant_body()
            for v in reversed(vars_):
                body = (q, v, body)
            return body
        if tok in NOT_TOK or tok.lower() == "not":
            self.eat()
            return ("not", self.unary())
        if tok in ("(", "["):
            close = ")" if tok == "(" else "]"
            # (∀x) body  -- parenthesised quantifier prefix
            if self.peek(1) in ("∀", "∃") and _is_ident(self.peek(2)) and self.peek(3) == close:
                self.eat(tok)
                q = QUANT[self.eat()]
                v = self.eat()
                self.eat(close)
                return (q, v, self.quant_body())
            self.eat(tok)
            n = self.parse_formula()
            self.eat(close)
            return n
        return self.atom()

    def quant_body(self) -> tuple:
        if self.wide:
            return self.parse_formula()
        tok = self.peek()
        if tok in ("(", "["):
            return self.unary()
        if self.is_quant_start() or tok in NOT_TOK:
            return self.unary()
        # "∀x P(x) → Q(x)" : without a group the body extends to the right (standard reading)
        return self.parse_formula()

    def term(self) -> tuple:
        tok = self.eat()
        if not _is_ident(tok):
            raise FOLParseError(f"bad term {tok!r}")
        if self.peek() == "(":
            raise FOLParseError(f"function term {tok}(...) unsupported")
        return ("t", tok)

    def atom(self) -> tuple:
        tok = self.peek()
        if not _is_ident(tok):
            raise FOLParseError(f"unexpected token {tok!r}")
        name = self.eat()
        if self.peek() == "(":
            self.eat("(")
            args = []
            if self.peek() == ")":
                self.eat(")")
                return ("atom", name, tuple())
            while True:
                args.append(self.term())
                if self.peek() == ",":
                    self.eat(",")
                    continue
                self.eat(")")
                break
            return ("atom", name, tuple(args))
        # equality between bare terms
        if self.peek() in ("=", "≠", "!="):
            op = self.eat()
            rhs = self.term()
            eq = ("eq", ("t", name), rhs)
            return ("not", eq) if op in ("≠", "!=") else eq
        if self.peek() in ("∈", "⊆", "⊂", "<", ">", "≤", "≥"):
            raise FOLParseError(f"unsupported relation {self.peek()!r}")
        return ("atom", name, tuple())


def _resolve(n: tuple, bound: frozenset, free_vars: set) -> tuple:
    op = n[0]
    if op in ("forall", "exists"):
        return (op, n[1], _resolve(n[2], bound | {n[1]}, free_vars))
    if op == "not":
        return ("not", _resolve(n[1], bound, free_vars))
    if op in SYM:
        return (op, _resolve(n[1], bound, free_vars), _resolve(n[2], bound, free_vars))
    if op in ("atom", "eq"):
        terms = n[2] if op == "atom" else n[1:]
        res = []
        for t in terms:
            name = t[1]
            if name in bound:
                res.append(("var", name))
            else:
                if VARLIKE.match(name):
                    free_vars.add(name)
                res.append(("const", name))
        return ("atom", n[1], tuple(res)) if op == "atom" else ("eq", res[0], res[1])
    raise FOLParseError(f"bad node {op}")


def _bound_names(n: tuple, acc: set) -> set:
    if n[0] in ("forall", "exists"):
        acc.add(n[1])
        _bound_names(n[2], acc)
    elif n[0] == "not":
        _bound_names(n[1], acc)
    elif n[0] in SYM:
        _bound_names(n[1], acc)
        _bound_names(n[2], acc)
    return acc


def _close(ast: tuple, names: list[str]) -> tuple:
    for v in sorted(names, reverse=True):
        ast = ("forall", v, ast)
    return ast


def _to_var(n: tuple, names: set) -> tuple:
    op = n[0]
    if op in ("forall", "exists"):
        return (op, n[1], _to_var(n[2], names - {n[1]} if False else names))
    if op == "not":
        return ("not", _to_var(n[1], names))
    if op in SYM:
        return (op, _to_var(n[1], names), _to_var(n[2], names))
    if op == "atom":
        return ("atom", n[1], tuple(("var", t[1]) if t[0] == "const" and t[1] in names else t for t in n[2]))
    if op == "eq":
        return ("eq",) + tuple(("var", t[1]) if t[0] == "const" and t[1] in names else t for t in n[1:])
    return n


FENCE = re.compile(r"```[a-zA-Z]*")


LATEX_WRAP = re.compile(r"\\(?:text|mathrm|mathit|textit|operatorname|mathsf|texttt)\s*\{([^{}]*)\}")


def clean_text(s: str) -> str:
    s = FENCE.sub(" ", s).replace("`", " ")
    s = LATEX_WRAP.sub(r"\1", s)
    for a, b in (("\\left(", "("), ("\\right)", ")"), ("\\left[", "("), ("\\right]", ")"), ("\\(", " "), ("\\)", " "),
                 ("\\[", " "), ("\\]", " "), ("\\,", " "), ("\\;", " "), ("\\!", ""), ("\\quad", " "),
                 ("\\wedge", "∧"), ("\\vee", "∨"), ("\\Rightarrow", "→"), ("\\Leftrightarrow", "↔"),
                 ("\\neq", "≠"), ("\\ne ", "≠ "), ("\\lnot", "¬"), ("\\neg", "¬")):
        s = s.replace(a, b)
    s = s.replace("$", " ").replace("\\forall", "∀").replace("\\exists", "∃").replace("\\neg", "¬")
    s = s.replace("\\land", "∧").replace("\\wedge", "∧").replace("\\lor", "∨").replace("\\vee", "∨")
    s = s.replace("\\rightarrow", "→").replace("\\to", "→").replace("\\leftrightarrow", "↔")
    s = s.replace("\\oplus", "⊕").replace("\\lnot", "¬").replace("\\iff", "↔").replace("\\implies", "→")
    s = s.replace("​", "").replace(" ", " ").replace("’", "'").replace("‘", "'")
    s = s.strip()
    s = re.sub(r"^(FOL|Formula|Answer|Output|Translation|First-order logic)\s*[:：]\s*", "", s, flags=re.I)
    s = re.sub(r"^\*\*|\*\*$", "", s).strip()
    s = s.rstrip(" .;")
    return s.strip()


def parse(s: str) -> ParseResult:
    """Parse a FOL string. Never raises; returns ParseResult(ok=False, error=...) on failure."""
    text = clean_text(s or "")
    if not text:
        return ParseResult(None, False, "empty", text=text)
    try:
        toks = tokenize(text)
    except FOLParseError as e:
        return ParseResult(None, False, f"tokenize: {e}", text=text)
    errors = []
    for wide in (False, True):
        try:
            p = _Parser(toks, wide)
            raw = p.parse_formula()
            if p.i != len(toks):
                raise FOLParseError(f"trailing tokens from {toks[p.i:p.i + 4]}")
            free: set = set()
            ast = _resolve(raw, frozenset(), free)
            notes = [] if not wide else ["wide_scope_reparse"]
            quantified = _bound_names(ast, set())
            if free & quantified and not wide:
                errors.append("free vars bound elsewhere; retry wide")
                continue
            if free:
                ast = _close(_to_var(ast, free), sorted(free))
                notes.append("implicit_universal_closure:" + ",".join(sorted(free)))
            return ParseResult(ast, True, "", notes, text)
        except (FOLParseError, IndexError, KeyError, RecursionError) as e:
            errors.append(str(e))
    return ParseResult(None, False, "; ".join(dict.fromkeys(errors)), text=text)


def to_str(n: tuple) -> str:
    op = n[0]
    if op in ("forall", "exists"):
        return ("∀" if op == "forall" else "∃") + n[1] + " " + _wrap(n[2], tight=True)
    if op == "not":
        return "¬" + _wrap(n[1], tight=True)
    if op in SYM:
        return f"{_wrap(n[1])} {SYM[op]} {_wrap(n[2])}"
    if op == "atom":
        return n[1] + ("(" + ", ".join(t[1] for t in n[2]) + ")" if n[2] else "")
    if op == "eq":
        return f"{n[1][1]} = {n[2][1]}"
    raise ValueError(op)


def _wrap(n: tuple, tight: bool = False) -> str:
    s = to_str(n)
    if n[0] in SYM or (n[0] == "eq") or (not tight and n[0] in ("forall", "exists")):
        return "(" + s + ")"
    return s


def signature(ast: tuple) -> tuple[dict[str, int], set[str]]:
    """Predicates {name: arity} and constants of a parsed formula (equality excluded)."""
    preds: dict[str, int] = {}
    consts: set[str] = set()

    def walk(n):
        op = n[0]
        if op in ("forall", "exists"):
            walk(n[2])
        elif op == "not":
            walk(n[1])
        elif op in SYM:
            walk(n[1]); walk(n[2])
        elif op in ("atom", "eq"):
            terms = n[2] if op == "atom" else n[1:]
            if op == "atom":
                key = n[1]
                if key in preds and preds[key] != len(terms):
                    key = f"{n[1]}/{len(terms)}"
                preds[key] = len(terms)
            for t in terms:
                if t[0] == "const":
                    consts.add(t[1])
    walk(ast)
    return preds, consts


def normalize_arity_overloads(ast: tuple) -> tuple:
    """Rename predicates used with two arities (P/1, P/2) so every name has one arity."""
    seen: dict[str, int] = {}
    clash: set[str] = set()

    def scan(n):
        if n[0] in ("forall", "exists"):
            scan(n[2])
        elif n[0] == "not":
            scan(n[1])
        elif n[0] in SYM:
            scan(n[1]); scan(n[2])
        elif n[0] == "atom":
            if n[1] in seen and seen[n[1]] != len(n[2]):
                clash.add(n[1])
            seen.setdefault(n[1], len(n[2]))
    scan(ast)
    if not clash:
        return ast

    def rw(n):
        if n[0] in ("forall", "exists"):
            return (n[0], n[1], rw(n[2]))
        if n[0] == "not":
            return ("not", rw(n[1]))
        if n[0] in SYM:
            return (n[0], rw(n[1]), rw(n[2]))
        if n[0] == "atom" and n[1] in clash:
            return ("atom", f"{n[1]}__{len(n[2])}", n[2])
        return n
    return rw(ast)


def complexity_ast(ast: tuple) -> dict:
    """n_quantifiers, nesting_depth (quantifier+connective nodes), n_connectives (→ ↔ ⊕ ∨ ¬)."""
    nq = 0
    ncon = 0

    def depth(n) -> int:
        nonlocal nq, ncon
        op = n[0]
        if op in ("forall", "exists"):
            nq += 1
            return 1 + depth(n[2])
        if op == "not":
            ncon += 1
            return 1 + depth(n[1])
        if op in SYM:
            if op != "and":
                ncon += 1
            return 1 + max(depth(n[1]), depth(n[2]))
        return 0
    d = depth(ast)
    return {"n_quantifiers": nq, "nesting_depth": d, "n_gold_connectives": ncon}


def has_quantifier(ast: tuple) -> bool:
    return complexity_ast(ast)["n_quantifiers"] > 0


def n_all_connectives(ast: tuple) -> int:
    c = 0

    def walk(n):
        nonlocal c
        if n[0] in ("forall", "exists"):
            walk(n[2])
        elif n[0] == "not":
            c += 1; walk(n[1])
        elif n[0] in SYM:
            c += 1; walk(n[1]); walk(n[2])
    walk(ast)
    return c


FORMULA_HINT = re.compile(r"[∀∃¬∧∨→↔⊕]|->|<->|\(")


def extract_formula(raw: str) -> str:
    """Pick the formula line out of a model response (first line with a quantifier/connective/'(')."""
    if raw is None:
        return ""
    txt = FENCE.sub("\n", raw)
    lines = [l.strip() for l in txt.splitlines() if l.strip()]
    cleaned = [clean_text(l) for l in lines]
    for l2 in cleaned:  # pass 1: a line carrying FOL operator symbols
        if re.search(r"[∀∃¬∧∨→↔⊕]|->|<->", l2) and not re.match(r"^[-*•]\s", l2):
            return l2
    for l2 in cleaned:  # pass 2: any line with a predicate call
        if re.match(r"^(here|the|this|note|explanation|sentence|let|where|to)\b", l2, re.I) or re.match(r"^[-*•]\s", l2):
            continue
        if FORMULA_HINT.search(l2):
            return l2
    return cleaned[0] if cleaned else ""

source_files.vendor/ds/fol_equiv.py:
"""Lexical-free FOL equivalence up to an arity-preserving bijection of predicates and constants.

L1 labeller. NO lexical information is used: predicate/constant NAMES never matter, only the
arity-grouped bijection. For every candidate mapping:
  1. cheap random-structure refutation in pure Python (sound: a disagreement IS a countermodel);
  2. bounded check by PROPOSITIONAL GROUNDING over domain {0..n-1}, n = 1..4, with z3 Bools per
     ground atom and Int-valued constant choice variables (a SAT answer is a countermodel ->
     sound non-equivalence; no EnumSort, so no sort-naming crashes);
  3. if no countermodel up to n=4: an UNBOUNDED z3 attempt (DeclareSort + quantifiers, 10 s):
     unsat -> equiv_proved, otherwise equiv_bounded.

Statuses: equiv_proved, equiv_bounded, non_equiv, non_equiv_no_bijection, unknown_capped,
unknown_timeout, unparseable.
"""
from __future__ import annotations

import itertools
import math
import random
import time
from collections import defaultdict

import z3

from fol_parse import SYM, normalize_arity_overloads, signature

MAX_MAPPINGS = 5040
BOUND_NS = (1, 2, 3, 4)


# ----------------------------------------------------------------------------- python evaluator
def _eval(n: tuple, interp: dict, consts: dict, env: dict, dom: range, pmap: dict | None) -> bool:
    op = n[0]
    if op == "atom":
        name = pmap.get(n[1], n[1]) if pmap else n[1]
        args = tuple(env[t[1]] if t[0] == "var" else consts[(pmap or {}).get("#" + t[1], t[1])] for t in n[2])
        return args in interp.get(name, ())
    if op == "eq":
        vals = [env[t[1]] if t[0] == "var" else consts[(pmap or {}).get("#" + t[1], t[1])] for t in n[1:]]
        return vals[0] == vals[1]
    if op == "not":
        return not _eval(n[1], interp, consts, env, dom, pmap)
    if op == "and":
        return _eval(n[1], interp, consts, env, dom, pmap) and _eval(n[2], interp, consts, env, dom, pmap)
    if op == "or":
        return _eval(n[1], interp, consts, env, dom, pmap) or _eval(n[2], interp, consts, env, dom, pmap)
    if op == "imp":
        return (not _eval(n[1], interp, consts, env, dom, pmap)) or _eval(n[2], interp, consts, env, dom, pmap)
    if op == "iff":
        return _eval(n[1], interp, consts, env, dom, pmap) == _eval(n[2], interp, consts, env, dom, pmap)
    if op == "xor":
        return _eval(n[1], interp, consts, env, dom, pmap) != _eval(n[2], interp, consts, env, dom, pmap)
    if op == "forall":
        v = n[1]
        old = env.get(v)
        res = True
        for d in dom:
            env[v] = d
            if not _eval(n[2], interp, consts, env, dom, pmap):
                res = False
                break
        env[v] = old
        return res
    if op == "exists":
        v = n[1]
        old = env.get(v)
        res = False
        for d in dom:
            env[v] = d
            if _eval(n[2], interp, consts, env, dom, pmap):
                res = True
                break
        env[v] = old
        return res
    raise ValueError(op)


def random_structures(preds: dict[str, int], consts: set[str], seed: int = 0, per_n: dict | None = None):
    rng = random.Random(seed)
    per_n = per_n or {1: 4, 2: 16, 3: 16}
    out = []
    for n, k in per_n.items():
        dom = range(n)
        for _ in range(k):
            dens = rng.choice([0.2, 0.5, 0.8])
            interp = {p: {t for t in itertools.product(dom, repeat=a) if rng.random() < dens} for p, a in preds.items()}
            cons = {c: rng.randrange(n) for c in consts}
            out.append((dom, interp, cons))
    return out


# ----------------------------------------------------------------------------- z3 grounding
class _Grounder:
    def __init__(self, n: int, pmap: dict | None, cvars: dict):
        self.n, self.pmap, self.cvars = n, pmap or {}, cvars
        self.atoms: dict = {}

    def cname(self, c):
        return self.pmap.get("#" + c, c)

    def bool_atom(self, name: str, args: tuple):
        key = (name, args)
        if key not in self.atoms:
            self.atoms[key] = z3.Bool(f"{name}|{'|'.join(map(str, args))}")
        return self.atoms[key]

    def term_choices(self, t, env):
        if t[0] == "var":
            return [(env[t[1]], None)]
        cv = self.cvars[self.cname(t[1])]
        return [(v, cv == v) for v in range(self.n)]

    def g(self, node, env):
        op = node[0]
        if op == "atom":
            name = self.pmap.get(node[1], node[1])
            choices = [self.term_choices(t, env) for t in node[2]]
            disj = []
            for combo in itertools.product(*choices):
                args = tuple(c[0] for c in combo)
                conds = [c[1] for c in combo if c[1] is not None]
                a = self.bool_atom(name, args)
                disj.append(z3.And(*conds, a) if conds else a)
            return disj[0] if len(disj) == 1 else z3.Or(*disj)
        if op == "eq":
            t1, t2 = node[1], node[2]
            if t1[0] == "var" and t2[0] == "var":
                return z3.BoolVal(env[t1[1]] == env[t2[1]])
            e1 = env[t1[1]] if t1[0] == "var" else self.cvars[self.cname(t1[1])]
            e2 = env[t2[1]] if t2[0] == "var" else self.cvars[self.cname(t2[1])]
            return e1 == e2
        if op == "not":
            return z3.Not(self.g(node[1], env))
        if op == "and":
            return z3.And(self.g(node[1], env), self.g(node[2], env))
        if op == "or":
            return z3.Or(self.g(node[1], env), self.g(node[2], env))
        if op == "imp":
            return z3.Implies(self.g(node[1], env), self.g(node[2], env))
        if op == "iff":
            return self.g(node[1], env) == self.g(node[2], env)
        if op == "xor":
            return z3.Xor(self.g(node[1], env), self.g(node[2], env))
        if op in ("forall", "exists"):
            parts = []
            for d in range(self.n):
                e2 = dict(env)
                e2[node[1]] = d
                parts.append(self.g(node[2], e2))
            return z3.And(*parts) if op == "forall" else z3.Or(*parts)
        raise ValueError(op)


def ground(ast: tuple, n: int, consts: list[str], pmap: dict | None = None, cvars: dict | None = None):
    if cvars is None:
        cvars = {c: z3.Int(f"c#{c}") for c in consts}
    return _Grounder(n, pmap, cvars).g(ast, {}), cvars


def _dom_constraints(cvars: dict, n: int):
    return [z3.And(v >= 0, v < n) for v in cvars.values()]


def bounded_check(F: tuple, G: tuple, consts: list[str], pmap: dict, mode: str, ns=BOUND_NS,
                  timeout_ms: int = 5000, deadline: float | None = None) -> tuple[str, int | None]:
    """mode 'equiv': SAT(F xor G); 'f2g': SAT(F ∧ ¬G); 'g2f': SAT(G ∧ ¬F).
    Returns ('countermodel', n) | ('none', max_n) | ('timeout', n)."""
    for n in ns:
        if deadline is not None and time.time() > deadline:
            return "timeout", n
        f, cv = ground(F, n, consts)
        g, _ = ground(G, n, consts, pmap=pmap, cvars=cv)
        s = z3.Solver()
        s.set("timeout", timeout_ms)
        s.add(*_dom_constraints(cv, n))
        if mode == "equiv":
            s.add(z3.Xor(f, g))
        elif mode == "f2g":
            s.add(f, z3.Not(g))
        else:
            s.add(g, z3.Not(f))
        r = s.check()
        if r == z3.sat:
            return "countermodel", n
        if r == z3.unknown:
            return "timeout", n
    return "none", ns[-1]


def unbounded_equiv(F: tuple, G: tuple, preds: dict[str, int], consts: list[str], pmap: dict,
                    timeout_ms: int = 10000) -> str:
    U = z3.DeclareSort("U")
    funcs = {p: (z3.Function(f"P_{p}", *([U] * a), z3.BoolSort()) if a > 0 else z3.Bool(f"P_{p}"))
             for p, a in preds.items()}
    cs = {c: z3.Const(f"K_{c}", U) for c in consts}

    def tr(node, env, remap):
        op = node[0]
        if op == "atom":
            name = remap.get(node[1], node[1]) if remap else node[1]
            args = [env[t[1]] if t[0] == "var" else cs[(remap or {}).get("#" + t[1], t[1])] for t in node[2]]
            f = funcs[name]
            return f(*args) if args else f
        if op == "eq":
            a = [env[t[1]] if t[0] == "var" else cs[(remap or {}).get("#" + t[1], t[1])] for t in node[1:]]
            return a[0] == a[1]
        if op == "not":
            return z3.Not(tr(node[1], env, remap))
        if op in ("and", "or", "imp", "iff", "xor"):
            a, b = tr(node[1], env, remap), tr(node[2], env, remap)
            return {"and": z3.And, "or": z3.Or, "imp": z3.Implies, "xor": z3.Xor}[op](a, b) if op != "iff" else a == b
        if op in ("forall", "exists"):
            v = z3.Const(f"v_{node[1]}_{id(node)}", U)
            e2 = dict(env)
            e2[node[1]] = v
            body = tr(node[2], e2, remap)
            return z3.ForAll([v], body) if op == "forall" else z3.Exists([v], body)
        raise ValueError(op)
    try:
        f = tr(F, {}, None)
        g = tr(G, {}, pmap)
        s = z3.Solver()
        s.set("timeout", timeout_ms)
        s.add(z3.Not(f == g))
        r = s.check()
        return "unsat" if r == z3.unsat else ("sat" if r == z3.sat else "unknown")
    except z3.Z3Exception:
        return "unknown"


# ----------------------------------------------------------------------------- mappings
def _groups(preds: dict[str, int]) -> dict[int, list[str]]:
    g = defaultdict(list)
    for p, a in preds.items():
        g[a].append(p)
    return {a: sorted(v) for a, v in g.items()}


def arity_profile(preds: dict[str, int], consts) -> tuple:
    g = _groups(preds)
    return tuple(sorted((a, len(v)) for a, v in g.items())) + (("c", len(consts)),)


def enumerate_mappings(cand_preds, cand_consts, gold_preds, gold_consts, fixed: dict | None = None,
                       cap: int = MAX_MAPPINGS, seed: int = 0):
    """Yield dicts gold_name -> cand_name (constants prefixed with '#'). Returns (iterator, capped)."""
    fixed = fixed or {}
    cg = _groups({p: a for p, a in cand_preds.items() if p not in fixed.values()})
    gg = _groups({p: a for p, a in gold_preds.items() if p not in fixed})
    cc = sorted(c for c in cand_consts if "#" + c not in fixed.values())
    gc = sorted(c for c in gold_consts if "#" + c not in fixed)
    blocks = [(gg[a], cg[a]) for a in sorted(gg)] + [(gc, cc)]
    total = math.prod(math.factorial(len(b[0])) for b in blocks)

    def mk(perms):
        m = dict(fixed)
        for (gl, cl), perm in zip(blocks, perms):
            is_c = gl is gc
            for gname, cname in zip(gl, perm):
                if is_c:
                    m["#" + gname] = "#" + cname
                else:
                    m[gname] = cname
        return m

    if total <= cap:
        it = (mk(p) for p in itertools.product(*[itertools.permutations(cl) for _, cl in blocks]))
        return it, False, total
    rng = random.Random(seed)

    def sampled():
        seen = set()
        tries = 0
        while len(seen) < cap and tries < cap * 3:
            tries += 1
            perms = tuple(tuple(rng.sample(cl, len(cl))) for _, cl in blocks)
            if perms in seen:
                continue
            seen.add(perms)
            yield mk(perms)
    return sampled(), True, total


def _pm_for_eval(m: dict) -> dict:
    """Mapping in the evaluator's convention: predicate names map directly; constants '#g'->'c'."""
    out = {}
    for k, v in m.items():
        if k.startswith("#"):
            out[k] = v[1:]
        else:
            out[k] = v
    return out


def _pm_for_z3(m: dict) -> dict:
    return _pm_for_eval(m)


# ----------------------------------------------------------------------------- main API
def equivalence(cand_ast: tuple | None, gold_ast: tuple | None, time_limit: float = 30.0,
                fixed: dict | None = None, want_entailment: bool = True, seed: int = 0) -> dict:
    """L1 status of candidate vs gold, lexical-free. `fixed` pins gold->cand names (used by L2)."""
    t0 = time.time()
    deadline = t0 + time_limit
    res = {"status": None, "mapping": None, "entail_cand_to_gold": None, "entail_gold_to_cand": None,
           "method": None, "max_domain": None, "n_mappings_total": None, "n_mappings_tried": 0,
           "seconds": None}
    if cand_ast is None or gold_ast is None:
        res["status"] = "unparseable"
        res["seconds"] = round(time.time() - t0, 3)
        return res
    C = normalize_arity_overloads(cand_ast)
    G = normalize_arity_overloads(gold_ast)
    cp, cc = signature(C)
    gp, gc = signature(G)
    if fixed is None and arity_profile(cp, cc) != arity_profile(gp, gc):
        res["status"] = "non_equiv_no_bijection"
        res["seconds"] = round(time.time() - t0, 3)
        return res
    if fixed is not None:
        # after substitution the free parts must still match by arity
        cp_free = {p: a for p, a in cp.items() if p not in fixed.values()}
        gp_free = {p: a for p, a in gp.items() if p not in fixed}
        if arity_profile(cp_free, cc) != arity_profile(gp_free, gc):
            res["status"] = "non_equiv_no_bijection"
            res["seconds"] = round(time.time() - t0, 3)
            return res
    maps, capped, total = enumerate_mappings(cp, cc, gp, gc, fixed=fixed, seed=seed)
    res["n_mappings_total"] = total
    structs = random_structures(cp, set(cc), seed=seed)
    cand_vals = [_eval(C, it, cs, {}, dom, None) for dom, it, cs in structs]
    consts_c = sorted(cc)
    best = None  # (score, mapping, f2g_alive, g2f_alive)
    survivors = []
    timed_out = False
    for m in maps:
        if time.time() > deadline:
            timed_out = True
            break
        res["n_mappings_tried"] += 1
        pm = _pm_for_eval(m)
        f2g = g2f = True
        eq_alive = True
        for (dom, it, cs), cv in zip(structs, cand_vals):
            gv = _eval(G, it, cs, {}, dom, pm)
            if cv and not gv:
                f2g = False
            if gv and not cv:
                g2f = False
            if cv != gv:
                eq_alive = False
                if not want_entailment or (not f2g and not g2f):
                    break
        score = int(f2g) + int(g2f)
        if best is None or score > best[0]:
            best = (score, m, f2g, g2f)
        if eq_alive:
            survivors.append(m)
            # bounded z3 check right away (early exit on the first equivalent mapping)
            r, n = bounded_check(C, G, consts_c, _pm_for_z3(m), "equiv", deadline=deadline)
            if r == "timeout":
                timed_out = True
                continue
            if r == "none":
                ub = unbounded_equiv(C, G, {**cp}, consts_c, _pm_for_z3(m),
                                     timeout_ms=int(max(1000, min(10000, (deadline - time.time()) * 1000))))
                res["status"] = "equiv_proved" if ub == "unsat" else "equiv_bounded"
                res["method"] = "unbounded" if ub == "unsat" else "bounded"
                res["max_domain"] = None if ub == "unsat" else BOUND_NS[-1]
                res["mapping"] = m
                res["entail_cand_to_gold"] = True
                res["entail_gold_to_cand"] = True
                res["seconds"] = round(time.time() - t0, 3)
                return res
    # no equivalent mapping found
    if timed_out:
        res["status"] = "unknown_timeout"
    elif capped:
        res["status"] = "unknown_capped"
    else:
        res["status"] = "non_equiv"
    res["method"] = "bounded"
    res["max_domain"] = BOUND_NS[-1]
    if want_entailment and best is not None and time.time() < deadline:
        _, m, f2g, g2f = best
        res["mapping"] = m
        pm = _pm_for_z3(m)
        for key, alive, mode in (("entail_cand_to_gold", f2g, "f2g"), ("entail_gold_to_cand", g2f, "g2f")):
            if not alive:
                res[key] = False
                continue
            r, _ = bounded_check(C, G, consts_c, pm, mode, deadline=deadline)
            res[key] = False if r == "countermodel" else (None if r == "timeout" else True)
    res["seconds"] = round(time.time() - t0, 3)
    return res


def sat_valid_check(ast: tuple, ns=(1, 2, 3), timeout_ms: int = 5000) -> dict:
    """Bounded satisfiability / validity of a single formula (for gold screening)."""
    A = normalize_arity_overloads(ast)
    preds, consts = signature(A)
    consts_l = sorted(consts)
    sat_any = False
    falsifiable_any = False
    for n in ns:
        f, cv = ground(A, n, consts_l)
        s = z3.Solver()
        s.set("timeout", timeout_ms)
        s.add(*_dom_constraints(cv, n))
        s.push()
        s.add(f)
        if s.check() == z3.sat:
            sat_any = True
        s.pop()
        s.add(z3.Not(f))
        if s.check() == z3.sat:
            falsifiable_any = True
        if sat_any and falsifiable_any:
            break
    return {"satisfiable": sat_any, "valid_bounded": not falsifiable_any, "unsat_bounded": not sat_any}

source_files.vendor/armB/latent_class.py:
"""Metric (iv): latent-class estimation of candidate correctness from cross-system agreement (no gold).

Per sentence, parseable candidates are clustered by solver equivalence (blind bijection; secondary:
trigram map). Latent z_s ∈ {class_1..class_K} ∪ {NONE}. One-coin model: system w's output lies in the
true class with prob p_w; two wrong outputs coincide with prob rho. P(some output correct) = pi.
Likelihood(z=c) = Π_{w∈c} p_w Π_{w∉c}(1-p_w) · rho^{#coincident wrong pairs} (1-rho)^{#other wrong pairs};
Likelihood(NONE) = Π_w (1-p_w) · (same coincidence term over all pairs). EM, 10 restarts.
Score(candidate) = posterior P(z_s = class(candidate)). Variants: Hui–Walter (pi, p_w per complexity
tercile), gold-as-4th-rater (no AUROC: circular), MAJ agreement, crowd-kit Dawid–Skene sanity row, B3sc.
"""
from __future__ import annotations

import itertools

import numpy as np
from loguru import logger


def _clusters(systems: list[str], parse_ok: dict, pairs: dict, key: str) -> dict[str, int]:
    parent = {s: s for s in systems}

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a
    for a, b in itertools.combinations(sorted(systems), 2):
        if not (parse_ok[a] and parse_ok[b]):
            continue
        p = pairs.get(f"{a}|{b}") or pairs.get(f"{b}|{a}")
        if p and p.get(key) == "equiv":
            parent[find(a)] = find(b)
    roots = {}
    out = {}
    for s in sorted(systems):
        r = find(s)
        out[s] = roots.setdefault(r, len(roots))
    return out


def build_obs(ss: dict, pairs: dict, key: str) -> list[dict]:
    sent = {s["sid"]: s for s in ss["sentences"]}
    by = {}
    for r in ss["real_items"]:
        by.setdefault(r["sid"], {})[r["system"]] = r
    obs = []
    for sid, items in by.items():
        systems = sorted(items)
        po = {s: bool(items[s]["parse_ok"]) for s in systems}
        cl = _clusters(systems, po, pairs.get(sid, {}), key)
        valid = sorted({cl[s] for s in systems if po[s]})
        obs.append({"sid": sid, "systems": systems, "cls": cl, "parse_ok": po, "valid": valid,
                    "tercile": sent[sid].get("tercile", 0)})
    return obs


def _lik(ob: dict, z, p: dict, rho: float) -> float:
    """z = class id or None."""
    L = 1.0
    wrong = []
    for s in ob["systems"]:
        if z is not None and ob["parse_ok"][s] and ob["cls"][s] == z:
            L *= p[s]
        else:
            L *= (1 - p[s])
            wrong.append(s)
    for a, b in itertools.combinations(wrong, 2):
        same = ob["parse_ok"][a] and ob["parse_ok"][b] and ob["cls"][a] == ob["cls"][b]
        L *= rho if same else (1 - rho)
    return L


def em(obs: list[dict], systems: list[str], groups: list[int] | None = None, n_iter: int = 200, tol: float = 1e-6,
       restarts: int = 10, seed: int = 0, fixed_p: dict | None = None) -> dict:
    """groups: per-observation population index (Hui–Walter: separate pi and p_w per population)."""
    rng = np.random.default_rng(seed)
    G = sorted(set(groups)) if groups is not None else [0]
    grp = groups if groups is not None else [0] * len(obs)
    best = None
    for r in range(restarts):
        if r == 0:
            p = {(g, s): 0.7 for g in G for s in systems}
            pi = {g: 0.8 for g in G}
            rho = 0.1
        else:
            p = {(g, s): float(rng.uniform(0.5, 0.95)) for g in G for s in systems}
            pi = {g: float(rng.uniform(0.5, 0.95)) for g in G}
            rho = float(rng.uniform(0.02, 0.3))
        if fixed_p:
            for g in G:
                for s, v in fixed_p.items():
                    p[(g, s)] = v
        prev = -np.inf
        for it in range(n_iter):
            ll = 0.0
            post = []
            for ob, g in zip(obs, grp):
                pw = {s: p[(g, s)] for s in ob["systems"]}
                K = len(ob["valid"])
                w = {}
                for c in ob["valid"]:
                    w[c] = pi[g] / K * _lik(ob, c, pw, rho)
                w[None] = (1 - pi[g]) * _lik(ob, None, pw, rho) if K > 0 else _lik(ob, None, pw, rho)
                Z = sum(w.values())
                ll += np.log(max(Z, 1e-300))
                post.append({k: v / Z for k, v in w.items()})
            # M-step
            num = {k: 1e-3 for k in p}
            den = {k: 2e-3 for k in p}
            pin = {g: 1e-3 for g in G}
            pid = {g: 2e-3 for g in G}
            rn, rd = 1e-3, 1e-2
            for ob, g, po in zip(obs, grp, post):
                pid[g] += 1
                pin[g] += 1 - po.get(None, 0.0)
                for s in ob["systems"]:
                    den[(g, s)] += 1
                    if ob["parse_ok"][s]:
                        num[(g, s)] += po.get(ob["cls"][s], 0.0)
                for z, pz in po.items():
                    wrong = [s for s in ob["systems"] if not (z is not None and ob["parse_ok"][s] and ob["cls"][s] == z)]
                    for a, b in itertools.combinations(wrong, 2):
                        rd += pz
                        if ob["parse_ok"][a] and ob["parse_ok"][b] and ob["cls"][a] == ob["cls"][b]:
                            rn += pz
            if not fixed_p:
                p = {k: min(0.999, max(0.001, num[k] / den[k])) for k in p}
            else:
                p = {k: (fixed_p[k[1]] if k[1] in fixed_p else min(0.999, max(0.001, num[k] / den[k]))) for k in p}
            pi = {g: min(0.999, max(0.001, pin[g] / pid[g])) for g in G}
            rho = min(0.999, max(0.001, rn / rd))
            if abs(ll - prev) < tol:
                break
            prev = ll
        if best is None or ll > best["ll"]:
            best = {"ll": float(ll), "p": dict(p), "pi": dict(pi), "rho": rho, "post": post, "iters": it + 1, "restart": r}
    return best


def run_latent_class(ss: dict, pairs: dict, alts: list[dict]) -> tuple[list[dict], dict]:
    systems = sorted({r["system"] for r in ss["real_items"]})
    rows, info = [], {}
    items = {r["item_id"]: r for r in ss["real_items"]}
    for key, metric in (("bij", "LC_onecoin"), ("str", "LC_onecoin_str")):
        obs = build_obs(ss, pairs, key)
        fit = em(obs, systems)
        info[metric] = {"loglik": fit["ll"], "p_w": {s: fit["p"][(0, s)] for s in systems}, "pi": fit["pi"][0],
                        "rho": fit["rho"], "iters": fit["iters"], "best_restart": fit["restart"],
                        "degenerate": bool(any(fit["p"][(0, s)] > 0.99 for s in systems) or fit["pi"][0] < 0.02)}
        logger.info(f"{metric}: {info[metric]}")
        for ob, po in zip(obs, fit["post"]):
            n_parse = sum(ob["parse_ok"].values())
            for s in ob["systems"]:
                iid = f"{ob['sid']}:{s}"
                cov = ob["parse_ok"][s] and n_parse >= 2
                sc = po.get(ob["cls"][s], 0.0) if ob["parse_ok"][s] else 0.0
                rows.append({"item_id": iid, "metric": metric, "score": sc, "covered": cov})
                if key == "bij":
                    size = sum(1 for s2 in ob["systems"] if ob["parse_ok"][s2] and ob["cls"][s2] == ob["cls"][s])
                    maj = (size - 1) / (n_parse - 1) if (ob["parse_ok"][s] and n_parse >= 2) else 0.0
                    rows.append({"item_id": iid, "metric": "LC_maj", "score": maj, "covered": cov})
        if key == "bij":
            # Hui–Walter variant: pi and p_w per complexity tercile
            hw = em(obs, systems, groups=[ob["tercile"] for ob in obs])
            info["LC_huiwalter"] = {"loglik": hw["ll"], "p_w": {f"{g}:{s}": v for (g, s), v in hw["p"].items()},
                                    "pi": {str(g): v for g, v in hw["pi"].items()}, "rho": hw["rho"]}
            for ob, po in zip(obs, hw["post"]):
                n_parse = sum(ob["parse_ok"].values())
                for s in ob["systems"]:
                    cov = ob["parse_ok"][s] and n_parse >= 2
                    rows.append({"item_id": f"{ob['sid']}:{s}", "metric": "LC_huiwalter",
                                 "score": po.get(ob["cls"][s], 0.0) if ob["parse_ok"][s] else 0.0, "covered": cov})
            # gold-as-4th-rater: gold joins the class of candidates bijection-equivalent to it (L_bij)
            obs_g = []
            for ob in obs:
                o2 = {**ob, "systems": ob["systems"] + ["GOLD"], "cls": dict(ob["cls"]), "parse_ok": dict(ob["parse_ok"])}
                gcls = None
                for s in ob["systems"]:
                    if items[f"{ob['sid']}:{s}"].get("L_bij") == "correct":
                        gcls = ob["cls"][s]
                if gcls is None:
                    gcls = max(ob["cls"].values()) + 1
                o2["cls"]["GOLD"] = gcls
                o2["parse_ok"]["GOLD"] = True
                o2["valid"] = sorted({o2["cls"][s] for s in o2["systems"] if o2["parse_ok"][s]})
                obs_g.append(o2)
            gg = em(obs_g, systems + ["GOLD"])
            sent = {s["sid"]: s for s in ss["sentences"]}
            cur_changed = [bool(sent[ob["sid"]].get("curated_changed")) for ob in obs if sent[ob["sid"]].get("curated_fol")]
            v1_vs_cur = [sent[ob["sid"]]["orig_vs_curated"]["label"] for ob in obs
                         if sent[ob["sid"]].get("orig_vs_curated")]
            info["LC_gold_as_rater"] = {"p_gold": gg["p"][(0, "GOLD")], "est_gold_error": 1 - gg["p"][(0, "GOLD")],
                                        "p_w": {s: gg["p"][(0, s)] for s in systems}, "pi": gg["pi"][0], "rho": gg["rho"],
                                        "observed_curated_changed_rate": (float(np.mean(cur_changed)) if cur_changed else None),
                                        "n_curated": len(cur_changed),
                                        "observed_v1_nonequiv_curated_rate": (float(np.mean([x != "equiv" for x in v1_vs_cur]))
                                                                              if v1_vs_cur else None),
                                        "note": "no AUROC for this variant (gold is the label source: circular)"}
            logger.info(f"gold-as-rater: {info['LC_gold_as_rater']}")
    # crowd-kit Dawid–Skene sanity row: task = candidate item, worker = each OTHER system, label = agrees (1/0)
    try:
        import pandas as pd
        from crowdkit.aggregation import DawidSkene
        obs = build_obs(ss, pairs, "bij")
        recs = []
        for ob in obs:
            for s in ob["systems"]:
                for s2 in ob["systems"]:
                    if s2 == s:
                        continue
                    ag = int(ob["parse_ok"][s] and ob["parse_ok"][s2] and ob["cls"][s] == ob["cls"][s2])
                    recs.append({"task": f"{ob['sid']}:{s}", "worker": s2, "label": ag})
        df = pd.DataFrame(recs)
        ds = DawidSkene(n_iter=100, tol=1e-5).fit(df)
        pr = ds.probas_
        col = 1 if 1 in pr.columns else pr.columns[-1]
        for ob in obs:
            n_parse = sum(ob["parse_ok"].values())
            for s in ob["systems"]:
                iid = f"{ob['sid']}:{s}"
                sc = float(pr.loc[iid, col]) if iid in pr.index else 0.5
                rows.append({"item_id": iid, "metric": "LC_ds_binary", "score": sc,
                             "covered": ob["parse_ok"][s] and n_parse >= 2})
        info["LC_ds_binary"] = {"priors": {str(k): float(v) for k, v in ds.priors_.items()}}
    except Exception as e:  # noqa: BLE001 - sanity row only
        logger.error(f"crowd-kit DawidSkene failed: {e!r}")
        info["LC_ds_binary"] = {"error": repr(e)}
    # B3sc zero-cost self-consistency against the same system's other translations of the sentence
    per = {}
    for a in alts:
        per.setdefault(a["primary_item_id"], []).append(a.get("equiv_to_primary"))
    for iid, r in items.items():
        eq = [x for x in per.get(iid, []) if x is not None]
        if not r["parse_ok"] or not eq:
            rows.append({"item_id": iid, "metric": "B3sc", "score": 0.5, "covered": False})
        else:
            rows.append({"item_id": iid, "metric": "B3sc", "score": float(np.mean([x == "equiv" for x in eq])),
                         "covered": True, "n_alts": len(eq)})
    return rows, info
